// 原受领/Q01和Known原pump后的本人销约；真实Task钱货/丢信责任/末ID候选回滚，不用替代writer。
#define main q01_cancellation_original_transaction_main
#include "task_personal_message_transaction_test.cpp"
#undef main
#include "resident/domains/tasks/personal_cancellations/task_personal_cancellation_contract.hpp"
#include "resident/domains/tasks/personal_cancellations/task_personal_cancellation_control.hpp"
#include "resident/domains/tasks/personal_cancellations/task_personal_cancellation_receipts.hpp"
#include "resident/domains/tasks/personal_cancellations/task_personal_cancellation_view.hpp"
namespace {
struct CancellationFixture:PersonalFixture {
 TaskPersonalCancellationCatalog cancel_catalog;TaskPersonalCancellationState cancelled;
 CancellationFixture(){catalog.offers.find("letter")->budget=12;auto d=ic.dialogues.back();d.id="private_sender";d.entry="cancel";d.nodes.front().id="cancel";d.nodes.front().text_key="sender_accepts_cancellation";ic.dialogues.push_back(d);known_catalog.templates.push_back({"private_sender","private_sender",{"installed_actor","player"},{"installed_actor","sender"}});cancel_catalog.policies.push_back({"original_cancel","letter","private_sender","cancel"});}
 TaskPersonalCancellationSources cancel_sources(){TaskPersonalCancellationSources x{sources(),cancel_catalog,cancelled};x.player_before=[this](Integer tick,const StableId& fact){return task_personal_cancellation_player_before(common,family,nullptr,tick,fact);};return x;}
 TaskPersonalCancellationServices cancel_services(){return {cancel_sources(),interaction,access};}
 void cancel_cold(){cold();auto valid=validate_task_personal_cancellations(cancel_sources());require(valid.ok,"original cancellation source: "+valid.error.original.code);}
 void accepted(){require(finish(start_original("accept_offer")).success,"real original acceptance before cancellation");}
 void open_sender(){end_talk();for(const auto* actor:{"player","sender"})common.state().actors.find(actor)->location=SettlementLocation{"town","away"};OpenKnownPersonalDialogue command{"sender","private_sender"};auto q=preview_known_personal_dialogue(*known_context,"player",command);require(q.ok,"actual original sender cancellation quote: "+q.error.original.code);const auto before=known_state;auto open=open_known_personal_dialogue_in_candidate(common,interaction,known_state,*known_context,"player",command,q.value);require(open.ok,"real Known opening and cancellation SAY: "+open.error.original.code);InteractionEffect effect;effect.settlement_result=open.value;ReceiptDetails details{effect,{}};auto fresh=known_personal_dialogue_new_player_source(&before,&known_state,"player","open_known_personal_dialogue",details,common.tick());require(fresh.ok,"actual sender opening difference");auto r=actual("open_known_personal_dialogue",details);require(bind_known_personal_dialogue_player_result(common,known_state,fresh.value,"player",request,*r).ok,"actual sender opening permanent result");}
 void execute(){auto service=cancel_services();auto q=preview_task_personal_cancellation(service,"player",{task_id});require(q.ok,"actual cancellation preview: "+q.error.original.code);const auto before=cancelled;auto applied=apply_task_personal_cancellation_in_candidate(common,tasks,cancelled,service,"player",{task_id},q.value);require(applied.ok,"original Task cancellation writer: "+applied.error.original.code);InteractionEffect effect;effect.settlement_result=applied.value;ReceiptDetails details{effect,{}};auto fresh=task_personal_cancellation_new_result_source(before,cancelled,"player",task_personal_cancellation_command,details,common.tick());require(fresh.ok,"actual new cancellation difference");auto r=actual(task_personal_cancellation_command,details);require(bind_task_personal_cancellation_result(common,cancelled,fresh.value,"player",request,*r).ok,"actual original Common result binds cancellation");cancel_cold();}
};
}
int run_personal_cancellation_transaction_component(){try{CancellationFixture f;f.accepted();require(f.common.wallet("cash:sender")->balance==88,"original sender funded exact task budget");require(!preview_task_personal_cancellation(f.cancel_services(),"player",{f.task_id}).ok,"old role conversation cannot replace cancellation Known SAY");f.open_sender();require(f.shared->roles.find("sender")->place_id=="market","original sender private role unmoved");f.execute();require(f.tasks.tasks.find(f.task_id)->status=="cancelled"&&f.common.wallet("cash:sender")->balance==100&&f.common.wallet("cash:player")->balance==100,"original budget refunded once without rewarding uncompleted task");require(f.common.count("bag:sender","letter",{{Owner::Kind::actor,"sender",{}}}).value==1&&f.common.count("bag:player","letter",{{Owner::Kind::task,f.task_id,{}}}).value==0,"original letter actually returned with sender ownership");require(!preview_task_personal_cancellation(f.cancel_services(),"player",{f.task_id}).ok,"closed task cannot refund twice");f.common.state().history.clear();f.common.state().results={};f.cancel_cold();auto old=f.cancelled;f.cancelled.cancellations.find(f.cancelled.cancellations.order().front())->actual_result.reset();require(!validate_task_personal_cancellations(f.cancel_sources()).ok,"full pruning does not remove actual cancellation binding");f.cancelled=old;
 CancellationFixture delivered;delivered.accepted();delivered.open_recipient();require(delivered.finish(delivered.deliver()).success,"real recipient delivery precedes cancellation");const auto handoff=delivered.tasks.message_handoffs->receipts.order().front();delivered.open_sender();delivered.execute();require(delivered.tasks.message_handoffs->receipts.find(handoff)&&delivered.common.count("bag:recipient","letter",{{Owner::Kind::actor,"recipient",{}}}).value==1,"cancellation preserves real recipient handoff and property");require(delivered.common.wallet("cash:player")->balance==100,"delivered but cancelled task does not invent report reward");
 CancellationFixture lost;lost.accepted();Owner owner{Owner::Kind::task,lost.task_id,{}};require(lost.common.apply_resources({{TransferLots{"bag:player","bag:stranger","letter",1,{owner},{},owner}},{}}).ok,"actual task-owned letter moved away without assigning stranger ownership");lost.open_sender();lost.execute();require(lost.common.count("bag:stranger","letter",{owner}).value==1,"remote original Task liability retained after cancellation");auto view=query_task_personal_cancellations(lost.cancel_services());require(view.ok,"limited original participant cancellation page");for(const auto& row:*view.value.find("rows")->as<BoundaryValue::Array>())require(!row.find("inventory_id")&&!row.find("lot_id"),"limited view cannot reveal remote lot location");
 CancellationFixture late;late.accepted();late.open_sender();auto q=preview_task_personal_cancellation(late.cancel_services(),"player",{late.task_id});require(q.ok,"late failure genuine sender quote");late.common.state().next_instance_id=std::numeric_limits<Integer>::max()-3;const auto snapshot=encode_common_state(late.common.state());const auto tasks=late.tasks;const auto state=late.cancelled;auto save=late.common.begin_savepoint();require(save.ok,"original Common candidate savepoint");auto result=apply_task_personal_cancellation_in_candidate(late.common,late.tasks,late.cancelled,late.cancel_services(),"player",{late.task_id},q.value);require(!result.ok&&result.error.original.code=="InstanceIdOverflow","last own fact ID failure after original cancellation transfer");require(late.common.wallet("cash:sender")->balance==100,"late failure occurred after original budget refund");require(late.common.rollback_savepoint(save.value).ok,"original Common rollback");late.tasks=tasks;late.cancelled=state;require(compare_boundary(snapshot,encode_common_state(late.common.state())).exact()&&late.cancelled.cancellations.empty(),"whole original refund and new cancellation source restored");late.cancel_cold();
 std::cout<<"Original Task/Known cancellation transaction source; runtime receipt is separate\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}

#ifndef HANMO_PERSONAL_TASK_TRANSACTIONS_COMPONENT
int main(){return run_personal_cancellation_transaction_component();}
#endif
